    OR (NEW.provider = 'paypal' AND (NEW.kind IS NOT 'payment' OR NEW.currency IS NOT 'USD' OR NEW.mode IS NULL OR NEW.mode NOT IN ('wallet', 'card', 'other') OR NEW.reference_norm IS NULL OR length(NEW.provider_payment_id) NOT BETWEEN 1 AND 64
